def findMaxConsecutiveOnes(nums):
    # Variable to track maximum count of ones
    max_count = 0
    # Loop over all possible starting positions
    for i in range(len(nums)):
        # If current element is not 1, skip
        if nums[i] != 1:
            continue
        # Count consecutive ones starting from index i
        current_count = 0
        for j in range(i, len(nums)):
            if nums[j] == 1:
                current_count += 1
            else:
                break
        # Update the max count found so far
        max_count = max(max_count, current_count)
    # Return the maximum consecutive ones count
    return max_count

def findPlatform(arr, dep, n):
    # Variable to store minimum platforms needed
    max_platforms = 0
    # Loop over each arrival and departure interval
    for i in range(n):
        # Count overlaps for interval of train i
        overlaps = 1
        for j in range(n):
            if i != j:
                # Check if train j is present at station when train i arrives
                if arr[i] >= arr[j] and arr[i] <= dep[j]:
                    overlaps += 1
        # Update maximum platform count
        max_platforms = max(max_platforms, overlaps)
    # Return the maximum platforms needed
    return max_platforms

def solveSudoku(board):
    # Coordinates of every blank cell, collected once up front
    empties = [(r, c) for r in range(9) for c in range(9) if board[r][c] == '.']

    # Judge a COMPLETELY filled grid: 9 distinct symbols in every unit
    def is_board_valid():
        for i in range(9):
            # Row i must hold 9 different digits
            if len(set(board[i])) != 9:
                return False
            # Column i must hold 9 different digits
            if len(set(board[r][i] for r in range(9))) != 9:
                return False
        # The nine 3x3 boxes, addressed by their top-left corner
        for br in range(0, 9, 3):
            for bc in range(0, 9, 3):
                # Flatten the 3x3 block into a list of 9 symbols
                box = [board[br + dr][bc + dc] for dr in range(3) for dc in range(3)]
                # Duplicates inside a box are illegal too
                if len(set(box)) != 9:
                    return False
        # Every row, column and box passed
        return True

    # Decide a digit for the k-th blank cell
    def fill(k):
        # All blanks filled -- only NOW do we ask whether the grid is legal
        if k == len(empties):
            return is_board_valid()
        r, c = empties[k]
        # Try all nine digits with no pruning whatsoever
        for digit in '123456789':
            # Write it even if it obviously clashes with a neighbour
            board[r][c] = digit
            # Recurse on the next blank cell
            if fill(k + 1):
                # A legal completed grid was found; leave it on the board
                return True
        # Nothing worked here, so undo and let the caller try another digit
        board[r][c] = '.'
        return False

    # Solve in place; the caller reads the answer out of `board`
    fill(0)

def solveSudoku(board):
    # Helper function to check if placing char 'c' is valid
    def isValid(row, col, c):
        # Check row, column and 3x3 grid
        for i in range(9):
            # Check row for duplicate
            if board[i][col] == c:
                return False
            # Check column for duplicate
            if board[row][i] == c:
                return False
            # Check 3x3 box for duplicate
            box_row = 3 * (row // 3) + i // 3
            box_col = 3 * (col // 3) + i % 3
            if board[box_row][box_col] == c:
                return False
        return True

    # Main recursive solver function
    def solve():
        for i in range(len(board)):
            for j in range(len(board[0])):
                # Check if cell is empty
                if board[i][j] == '.':
                    # Try placing characters '1' to '9'
                    for c in '123456789':
                        # If valid to place
                        if isValid(i, j, c):
                            # Place character on the board
                            board[i][j] = c
                            # Recurse to solve next cells
                            if solve():
                                return True
                            else:
                                # Backtrack: reset cell if it fails later
                                board[i][j] = '.'
                    # Return False if no character 1-9 fits here
                    return False
        # Board is completely solved
        return True

    # Trigger the solver
    solve()

def graphColoring(graph, m, N):
    # Judge a COMPLETE assignment: no edge may join two equal colours
    def isValid(color):
        for i in range(N):
            for j in range(N):
                # graph[i][j] == 1 means i and j are adjacent
                if graph[i][j] == 1 and color[i] == color[j] and i != j:
                    return False
        # Every edge connects two differently coloured vertices
        return True

    # Assign a colour to `vertex`, with no pruning at all
    def solve(vertex, color):
        # All N vertices coloured -- only now do we test the assignment
        if vertex == N:
            return isValid(color)
        # Try every colour, legal or not
        for col in range(1, m + 1):
            # Paint the vertex and keep going
            color[vertex] = col
            # Recurse to colour the remaining vertices
            if solve(vertex + 1, color):
                return True
            # That colour led nowhere; unpaint before trying the next one
            color[vertex] = 0
        # No colour worked for this vertex
        return False

    # 0 means "uncoloured"; real colours are 1..m
    color = [0] * N
    # Start colouring from vertex 0
    return solve(0, color)

def graphColoring(graph, m, N):
    # Array to store color assigned to each vertex
    color = [0] * N

    # Helper function to check if it's safe to color vertex 'v' with color 'col'
    def isSafe(v, col):
        # Check all other vertices
        for i in range(N):
            # If there is an edge and the neighbor has the same color, it is not safe
            if graph[v][i] == 1 and color[i] == col:
                return False
        # Safe to color
        return True

    # Recursive function to solve coloring problem
    def solve(v):
        # Base Case: If all vertices are colored, return True
        if v == N:
            return True
        # Try different colors for vertex v
        for col in range(1, m + 1):
            # Check if assigning color 'col' is safe
            if isSafe(v, col):
                # Assign color to vertex v
                color[v] = col
                # Recurse to color the rest of the vertices
                if solve(v + 1):
                    return True
                # Backtrack: Reset color assignment
                color[v] = 0
        # If no color can be assigned, return False
        return False

    # Start solver from vertex 0
    return solve(0)

def wordBreak(s, wordDict):
    # Set for O(1) word validation
    word_set = set(wordDict)
    # Recursive helper
    def solve(start):
        # Base case: reached end of string
        if start == len(s):
            return True
        # Try all possible ending indices for current word segment
        for end in range(start + 1, len(s) + 1):
            # If current substring is in dict, solve recursively for remaining
            if s[start:end] in word_set:
                if solve(end):
                    return True
        # Return False if no valid partition works
        return False
    return solve(0)

def NthRoot(n, m):
    # Iterate starting from 1
    for i in range(1, m + 1):
        # Calculate power i^n
        val = i ** n
        # If we reach target, return i
        if val == m:
            return i
        # If we exceed target, root cannot be an integer
        elif val > m:
            return -1
    return -1

class MyStack:
    def __init__(self):
        # Standard list to store stack elements
        self.stack = []

    def push(self, x: int) -> None:
        # Append element to stack list
        self.stack.append(x)

    def pop(self) -> int:
        # Check if stack is empty, return -1
        if not self.stack:
            return -1
        # Pop from end of list
        return self.stack.pop()

    def top(self) -> int:
        # Check if stack is empty, return -1
        if not self.stack:
            return -1
        # Peek last element of list
        return self.stack[-1]

    def isEmpty(self) -> bool:
        # Check if stack is empty
        return len(self.stack) == 0

    def size(self) -> int:
        # Return stack size
        return len(self.stack)

class MyQueue:
    def __init__(self):
        # Standard Python list used as the backing store
        self.queue = []

    def enqueue(self, x: int) -> bool:
        # Append to the end of the list — this end is the REAR of the queue
        self.queue.append(x)
        # A Python list grows on demand, so an enqueue can never fail here
        return True

    def dequeue(self) -> int:
        # Empty queue: report underflow with the -1 sentinel instead of crashing
        if not self.queue:
            return -1
        # pop(0) removes the FRONT, but every remaining element shifts one slot left
        # That shifting is what makes this dequeue O(N) and motivates the circular array
        return self.queue.pop(0)

    def front(self) -> int:
        # Nothing to peek at when the queue is empty
        if not self.queue:
            return -1
        # Index 0 is the oldest element still in the queue
        return self.queue[0]

    def isEmpty(self) -> bool:
        # A list with no elements means an empty queue
        return len(self.queue) == 0

    def size(self) -> int:
        # len() of the backing list is the number of live elements
        return len(self.queue)

from collections import deque

class MyStack:
    def __init__(self):
        # Primary queue: its FRONT always holds the current stack top
        self.q1 = deque()
        # Helper queue: empty between pushes, used as scratch space
        self.q2 = deque()

    def push(self, x: int) -> None:
        # Put the new element into the EMPTY helper queue first
        self.q2.append(x)
        # Move all older elements from q1 behind x, preserving their order
        while self.q1:
            # popleft() takes q1's front, append() drops it at q2's back
            self.q2.append(self.q1.popleft())
        # Swap the names: q2 (correct order) becomes the live queue, q1 becomes scratch
        self.q1, self.q2 = self.q2, self.q1

    def pop(self) -> int:
        # Guard against underflow instead of letting popleft() raise IndexError
        if not self.q1:
            return -1
        # The front of q1 is the most recently pushed element
        return self.q1.popleft()

    def top(self) -> int:
        # Same empty guard as pop, but we do not remove anything
        if not self.q1:
            return -1
        # Peek the front without consuming it
        return self.q1[0]

    def empty(self) -> bool:
        # The stack is empty exactly when the primary queue holds nothing
        return len(self.q1) == 0

from collections import deque  # deque gives O(1) append at the back and popleft at the front

class MyStack:
    def __init__(self):
        # Use collections.deque as the underlying queue
        self.q = deque()

    def push(self, x: int) -> None:
        # Add element to the queue
        self.q.append(x)
        # Rotate all previous elements to the back of the queue
        for _ in range(len(self.q) - 1):
            self.q.append(self.q.popleft())  # take the front element and send it to the back

    def pop(self) -> int:
        # Remove and return the front element of the queue
        if not self.q:
            return -1
        return self.q.popleft()  # after push's rotation the front IS the newest element

    def top(self) -> int:
        # Peek and return the front element of the queue
        if not self.q:
            return -1
        return self.q[0]  # same element pop would return, but left in place

    def empty(self) -> bool:
        # Return true if queue length is 0
        return len(self.q) == 0

class MyQueue:
    def __init__(self):
        # Main stack: kept so that its TOP is the oldest element (the queue front)
        self.s1 = []
        # Helper stack used only while a push is in progress
        self.s2 = []

    def push(self, x: int) -> None:
        # Empty s1 into s2 — pouring a stack into a stack reverses the order
        while self.s1:
            self.s2.append(self.s1.pop())
        # s1 is empty now, so x lands on the bottom of the rebuilt stack
        self.s1.append(x)
        # Pour everything back so the older elements sit above x again
        while self.s2:
            # Each element returns to s1 in its original relative order
            self.s1.append(self.s2.pop())

    def pop(self) -> int:
        # Guard the underflow case instead of letting pop() raise IndexError
        if not self.s1:
            return -1
        # The top of s1 is the element that was pushed earliest
        return self.s1.pop()

    def peek(self) -> int:
        # Same guard, but nothing is removed
        if not self.s1:
            return -1
        # Index -1 is the top of a Python list used as a stack
        return self.s1[-1]

    def empty(self) -> bool:
        # Everything always lives in s1 here, so one length check is enough
        return len(self.s1) == 0

class MyQueue:
    def __init__(self):
        # Stack to handle incoming elements
        self.input_stack = []
        # Stack to handle outgoing elements
        self.output_stack = []

    def push(self, x: int) -> None:
        # Push element to the input stack
        self.input_stack.append(x)

    def pop(self) -> int:
        # Ensure the output stack is not empty
        if not self.output_stack:
            # Transfer elements from input to output in reverse order
            while self.input_stack:
                self.output_stack.append(self.input_stack.pop())
        # Return and remove the top of output stack
        if not self.output_stack:
            return -1
        return self.output_stack.pop()

    def peek(self) -> int:
        # Ensure the output stack has the current elements
        if not self.output_stack:
            # Transfer elements from input to output
            while self.input_stack:
                self.output_stack.append(self.input_stack.pop())
        # Return the top of output stack without removing
        if not self.output_stack:
            return -1
        return self.output_stack[-1]

    def empty(self) -> bool:
        # Queue is empty if both stacks are empty
        return not self.input_stack and not self.output_stack

def sortStack(stack):
    # Helper list to sort the stack elements
    arr = []
    while stack:
        arr.append(stack.pop())
    # Sort the array
    arr.sort()
    # Push sorted elements back to stack
    for x in arr:
        stack.append(x)

class MinStack:
    def __init__(self):
        # Standard list to store stack elements
        self.stack = []

    def push(self, val: int) -> None:
        # Append element
        self.stack.append(val)

    def pop(self) -> None:
        # Pop top element
        self.stack.pop()

    def top(self) -> int:
        # Return top element value
        return self.stack[-1]

    def getMin(self) -> int:
        # Search minimum in O(N)
        return min(self.stack)

class MinStack:
    def __init__(self):
        # List of tuples: (value, current_min)
        self.stack = []

    def push(self, val: int) -> None:
        # Determine the new minimum
        current_min = val
        if self.stack:
            current_min = min(val, self.stack[-1][1])
        # Append value and minimum tuple
        self.stack.append((val, current_min))

    def pop(self) -> None:
        # Remove top element
        self.stack.pop()

    def top(self) -> int:
        # Return top element value
        return self.stack[-1][0]

    def getMin(self) -> int:
        # Return current minimum
        return self.stack[-1][1]

def longestPalindrome(s: str) -> str:
    # Return empty string if input is empty
    if not s:
        return ""

    n = len(s)
    longest = ""

    # Iterate over all possible starting positions of substrings
    for i in range(n):
        # Iterate over all possible ending positions
        for j in range(i, n):
            substring = s[i:j+1]
            # Check if current substring is equal to its reverse
            if substring == substring[::-1]:
                # If this palindrome is longer than the previous maximum, update it
                if len(substring) > len(longest):
                    longest = substring

    # Return the longest palindromic substring found
    return longest

def longestCommonPrefix(strs: list[str]) -> str:
    if not strs:
        return ""

    # Iterate through the indices of the first string
    for i in range(len(strs[0])):
        char = strs[0][i]
        # Compare this character with the same index of all other strings
        for j in range(1, len(strs)):
            # If current string is shorter or has a different character, return current prefix
            if i >= len(strs[j]) or strs[j][i] != char:
                return strs[0][:i]

    # Return the entire first string if no mismatch is found
    return strs[0]

def longestCommonPrefix(strs: list[str]) -> str:
    # If the input list is empty, return empty string
    if not strs:
        return ""

    # Assume the first string is the starting prefix
    prefix = strs[0]

    # Compare the prefix with each string in the list
    for i in range(1, len(strs)):
        # Shrink the prefix until strs[i] starts with the prefix
        while not strs[i].startswith(prefix):
            prefix = prefix[:-1]
            # If prefix becomes empty, return immediately
            if not prefix:
                return ""

    # Return the longest common prefix
    return prefix

def rabinKarp(text: str, pattern: str) -> int:
    n, m = len(text), len(pattern)
    # If pattern is longer than text, it cannot match
    if m > n:
        return -1

    # Check every starting position in the text
    for i in range(n - m + 1):
        # Check if the substring matches the pattern
        if text[i:i+m] == pattern:
            return i

    # Return -1 if not found
    return -1

def zFunction(s: str) -> list[int]:
    n = len(s)
    z = [0] * n

    # Loop through each position from 1 to n-1
    for i in range(1, n):
        # Compare characters starting from i with the prefix
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1

    # Return the computed Z-array
    return z

def isAnagram(s: str, t: str) -> bool:
    # If lengths are not equal, they cannot be anagrams
    if len(s) != len(t):
        return False

    # Sort characters of both strings and compare them
    return sorted(s) == sorted(t)

def isBalanced(root):
    # Helper function returns height if balanced, else -1
    def check(node):
        # Base case: empty node has height 0
        if not node:
            return 0
        # Get height of left subtree
        left_h = check(node.left)
        # If left subtree is unbalanced, propagate -1 upwards
        if left_h == -1:
            return -1
        # Get height of right subtree
        right_h = check(node.right)
        # If right subtree is unbalanced, propagate -1 upwards
        if right_h == -1:
            return -1
        # If heights differ by more than 1, current subtree is unbalanced
        if abs(left_h - right_h) > 1:
            return -1
        # Return actual height of current node
        return 1 + max(left_h, right_h)

    # Root is balanced if check does not return -1
    return check(root) != -1

def diameterOfBinaryTree(root):
    # Helper to compute height of a subtree
    def height(node):
        if not node:
            return 0
        return 1 + max(height(node.left), height(node.right))

    # Base case: empty node has diameter 0
    if not root:
        return 0
    # Calculate left and right heights
    left_h = height(root.left)
    right_h = height(root.right)
    # Diameter through current root
    curr_diameter = left_h + right_h
    # Recurse on left and right subtrees
    left_diameter = diameterOfBinaryTree(root.left)
    right_diameter = diameterOfBinaryTree(root.right)
    # Return maximum of all diameters
    return max(curr_diameter, left_diameter, right_diameter)

def maxPathSum(root):
    # Helper to compute max branch sum from a node
    def max_branch(node):
        if not node:
            return 0
        # Return maximum branch sum (must be non-negative)
        return max(0, node.val + max(max_branch(node.left), max_branch(node.right)))

    # Base case
    if not root:
        return float('-inf')
    # Calculate max path sum passing through root
    left_contrib = max(0, max_branch(root.left))
    right_contrib = max(0, max_branch(root.right))
    curr_sum = root.val + left_contrib + right_contrib
    # Recurse on children
    left_max = maxPathSum(root.left)
    right_max = maxPathSum(root.right)
    # Return maximum of all
    return max(curr_sum, left_max, right_max)

def isSameTree(p, q):
    # If both nodes are null, trees are identical from here
    if not p and not q:
        return True
    # If one node is null and the other is not, they are not identical
    if not p or not q:
        return False
    # If values of current nodes do not match, they are not identical
    if p.val != q.val:
        return False
    # Recursively check left subtrees and right subtrees
    return isSameTree(p.left, q.left) and isSameTree(p.right, q.right)

def isSymmetric(root):
    # Helper function to check if two subtrees are mirrors of each other
    def isMirror(t1, t2):
        # If both subtrees are null, they are symmetric
        if not t1 and not t2:
            return True
        # If only one is null, they are not symmetric
        if not t1 or not t2:
            return False
        # Check if current values match and their subtrees are mirrored
        return (t1.val == t2.val and 
                isMirror(t1.left, t2.right) and 
                isMirror(t1.right, t2.left))

    # If root is null, it is symmetric
    if not root:
        return True
    # Check if left and right subtrees are mirrors of each other
    return isMirror(root.left, root.right)

def countNodes(root):
    # Base case: if root is None, return 0
    if not root:
        return 0
    # Count 1 for the root, plus recursive count of left and right subtrees
    return 1 + countNodes(root.left) + countNodes(root.right)

def insertIntoBST(root, val):
    # If root is None, return new node
    if not root:
        return TreeNode(val)
    # Pointer to traverse the BST
    curr = root
    # Loop to find the insertion point
    while True:
        # If value is smaller than current node
        if val < curr.val:
            # If left child exists, move left
            if curr.left:
                curr = curr.left
            # If left child is None, insert here
            else:
                curr.left = TreeNode(val)
                break
        # If value is larger than current node
        else:
            # If right child exists, move right
            if curr.right:
                curr = curr.right
            # If right child is None, insert here
            else:
                curr.right = TreeNode(val)
                break
    # Return the root of BST
    return root

def knapsack(W: int, wt: list[int], val: list[int]) -> int:
    n = len(wt)
    # Define recursive helper function
    def helper(idx, rem_w):
        # Base Case: no items left or knapsack is full
        if idx == n or rem_w == 0:
            # Return 0 value
            return 0
        # If weight of current item exceeds remaining capacity, skip it
        if wt[idx] > rem_w:
            return helper(idx + 1, rem_w)
        # Case 1: Pick the current item
        take = val[idx] + helper(idx + 1, rem_w - wt[idx])
        # Case 2: Skip the current item
        skip = helper(idx + 1, rem_w)
        # Return the maximum of both choices
        return max(take, skip)
    # Start search from index 0
    return helper(0, W)

def unboundedKnapsack(W: int, wt: list[int], val: list[int]) -> int:
    n = len(wt)
    # Recursive helper function
    def helper(rem_w):
        # Base Case: if remaining weight is 0 or less, value is 0
        if rem_w <= 0:
            return 0
        max_val = 0
        # Check every item for inclusion
        for i in range(n):
            # If item weight fits in remaining capacity
            if wt[i] <= rem_w:
                # Update max_val by including this item
                max_val = max(max_val, val[i] + helper(rem_w - wt[i]))
        # Return maximum value possible with capacity rem_w
        return max_val
    # Call helper with full capacity
    return helper(W)

def unboundedKnapsack(W: int, wt: list[int], val: list[int]) -> int:
    n = len(wt)
    # Initialize dp array of size W + 1 with 0s
    dp = [0] * (W + 1)
    # Compute max value for every capacity from 1 to W
    for w in range(1, W + 1):
        # Check each item to see if it can fit in current capacity w
        for i in range(n):
            if wt[i] <= w:
                # Update DP table with the best value
                dp[w] = max(dp[w], dp[w - wt[i]] + val[i])
    # Return the maximum value for capacity W
    return dp[W]

def cutRod(price: list[int], n: int) -> int:
    # Helper recursive function
    def helper(rem_len):
        # Base Case: if remaining length is 0, no price
        if rem_len == 0:
            return 0
        max_val = 0
        # Try cutting at every possible length from 1 to rem_len
        for i in range(1, rem_len + 1):
            # Update max_val with best cut
            max_val = max(max_val, price[i - 1] + helper(rem_len - i))
        return max_val
    # Call helper with initial length n
    return helper(n)

def longestCommonSubsequence(text1: str, text2: str) -> int:
    # Brute force: pure recursion over "where am I in each string", nothing remembered.
    def solve(i: int, j: int) -> int:
        # Base case: one string is exhausted, so no further characters can be matched.
        if i == len(text1) or j == len(text2):
            return 0                                # empty tail contributes length 0
        if text1[i] == text2[j]:                    # the two front characters agree
            # Taking a matching pair is always safe, so consume BOTH and count it.
            return 1 + solve(i + 1, j + 1)
        # They differ, so one of them can never be part of this alignment. We do not know
        # which, so try dropping each in turn and keep whichever branch scores higher.
        return max(solve(i + 1, j), solve(i, j + 1))

    return solve(0, 0)                              # start at the front of both strings

def longestCommonSubstring(S1: str, S2: str) -> int:
    n, m = len(S1), len(S2)
    max_len = 0
    # Generate all starting indices of S1
    for i in range(n):
        # Generate all ending indices of S1
        for j in range(i + 1, n + 1):
            substring = S1[i:j]
            # Check if this substring exists in S2
            if substring in S2:
                # Update max_len if this substring is longer
                max_len = max(max_len, len(substring))
    return max_len

def longestPalindromeSubseq(s: str) -> int:
    # Recursive helper with left index i and right index j
    def helper(i, j):
        # Base Case: empty substring
        if i > j:
            return 0
        # Base Case: single character substring is always a palindrome
        if i == j:
            return 1
        # If boundary characters match, add 2 and move inwards
        if s[i] == s[j]:
            return 2 + helper(i + 1, j - 1)
        # Otherwise, try skipping left character or right character
        return max(helper(i + 1, j), helper(i, j - 1))
    # Start search from the full string boundaries
    return helper(0, len(s) - 1)

def minDistance(word1: str, word2: str) -> int:
    # Recursive helper with lengths i and j
    def helper(i, j):
        # If word1 is exhausted, we need to insert all word2 chars
        if i == 0:
            return j
        # If word2 is exhausted, we need to delete all word1 chars
        if j == 0:
            return i
        # If characters match, no operation needed
        if word1[i - 1] == word2[j - 1]:
            return helper(i - 1, j - 1)
        # Else try insert, delete, replace and take min
        return 1 + min(
            helper(i, j - 1),    # Insert
            helper(i - 1, j),    # Delete
            helper(i - 1, j - 1) # Replace
        )
    return helper(len(word1), len(word2))

def minDistance(word1: str, word2: str) -> int:
    m, n = len(word1), len(word2)
    # Initialize 2D DP array with size (m+1) x (n+1)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    # Base cases: converting string of length i to empty string requires i deletions
    for i in range(m + 1):
        dp[i][0] = i
    # Base cases: converting empty string to string of length j requires j insertions
    for j in range(n + 1):
        dp[0][j] = j
    # Populate DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            # If characters match, no operation cost is added
            if word1[i - 1] == word2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                # Min of insert, delete, replace + 1
                dp[i][j] = 1 + min(
                    dp[i][j - 1],    # Insert
                    dp[i - 1][j],    # Delete
                    dp[i - 1][j - 1] # Replace
                )
    # Return the edit distance at bottom-right cell
    return dp[m][n]

def numDistinct(s: str, t: str) -> int:
    # Helper recursive function
    def helper(i, j):
        # Base Case: all of t is matched
        if j == len(t):
            return 1
        # Base Case: s is exhausted but t is not
        if i == len(s):
            return 0
        # If characters match, try both matching this char and skipping it
        if s[i] == t[j]:
            return helper(i + 1, j + 1) + helper(i + 1, j)
        # Else, skip this character of s
        return helper(i + 1, j)
    return helper(0, 0)

def matrixMultiplication(arr: list[int]) -> int:
    # Recursive helper function
    def helper(i, j):
        # Base Case: single matrix has 0 multiplication cost
        if i == j:
            return 0
        min_cost = float('inf')
        # Try all split points k between i and j-1
        for k in range(i, j):
            # Cost = left chain cost + right chain cost + multiplication cost of results
            cost = helper(i, k) + helper(k + 1, j) + arr[i - 1] * arr[k] * arr[j]
            min_cost = min(min_cost, cost)
        return min_cost
    # Call helper with first matrix index 1 and last matrix index N-1
    return helper(1, len(arr) - 1)

def maxProfit(prices: List[int]) -> int:
    n = len(prices)  # total number of days
    best = 0  # best profit seen so far (0 = never trade)
    # Try every possible buy day
    for buy in range(n):
        # Pair it with every strictly later sell day
        for sell in range(buy + 1, n):
            # Profit if we buy on 'buy' and sell on 'sell'
            profit = prices[sell] - prices[buy]
            # Keep this pair only if it beats the current best
            if profit > best:
                best = profit
    return best  # maximum profit over all valid (buy, sell) pairs

def rotate(matrix: List[List[int]]) -> None:
    n = len(matrix)  # square size
    # Build a brand-new rotated matrix (costs O(n^2) extra space)
    rotated = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            # Rule: value at (i, j) lands at (j, n-1-i) after a CW turn
            rotated[j][n - 1 - i] = matrix[i][j]
    # Copy the answer back so the caller sees an in-place change
    for i in range(n):
        for j in range(n):
            matrix[i][j] = rotated[i][j]  # overwrite cell by cell

def rotate(matrix: List[List[int]]) -> None:
    n = len(matrix)  # the matrix is n x n
    # Step 1: transpose — mirror every cell across the main diagonal
    for i in range(n):
        # j starts at i + 1 so each pair (i,j)/(j,i) swaps exactly once
        for j in range(i + 1, n):
            # Swap the cell with its mirror across the diagonal
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]
    # Step 2: reverse every row to finish the 90-degree clockwise turn
    for row in matrix:
        # In-place left-right flip of one row
        row.reverse()

def merge(intervals: List[List[int]]) -> List[List[int]]:
    intervals = sorted(intervals)  # sort by start so overlap candidates sit together
    n = len(intervals)  # total interval count
    ans = []  # finished, disjoint blocks
    for i in range(n):
        start, end = intervals[i]  # seed a candidate block from interval i
        # Already swallowed by the last sealed block? Then skip this seed.
        if ans and end <= ans[-1][1]:
            continue
        # Re-scan every later interval and absorb all that touch [start, end]
        for j in range(i + 1, n):
            if intervals[j][0] <= end:
                end = max(end, intervals[j][1])  # extend the right edge
        ans.append([start, end])  # seal the fully-grown block
    return ans  # disjoint intervals covering the same points

def merge(nums1: List[int], m: int, nums2: List[int], n: int) -> None:
    # Copy every nums2 element into the spare zero slots at nums1's tail
    for j in range(n):
        nums1[m + j] = nums2[j]  # slot m+j is guaranteed to be free
    # nums1 now holds all m+n values, just unordered — sorting fixes that
    nums1.sort()  # Timsort: O((m+n) log (m+n)) time

def findDuplicate(nums: List[int]) -> int:
    n = len(nums)  # n+1 numbers with values in 1..n
    # Compare every pair of positions — the definition of "duplicate"
    for i in range(n):
        for j in range(i + 1, n):
            # Same value at two different indices = the repeated number
            if nums[i] == nums[j]:
                return nums[i]
    return -1  # unreachable: a duplicate is guaranteed to exist

def findDuplicate(nums: List[int]) -> int:
    seen = set()  # values met so far; O(1) average membership test
    for x in nums:
        # If x was already met at an earlier index, it is the duplicate
        if x in seen:
            return x
        seen.add(x)  # first sighting of x: remember it
    return -1  # unreachable: a duplicate is guaranteed

def findRepeatMissing(nums: List[int]) -> List[int]:
    n = len(nums)  # values are supposed to be 1..n
    repeat, missing = -1, -1  # placeholders until each is found
    # For every value v that SHOULD appear, count how often it really does
    for v in range(1, n + 1):
        count = 0  # occurrences of v in the array
        for x in nums:
            if x == v:
                count += 1  # one more sighting of v
        if count == 2:
            repeat = v   # v appears twice -> it is the repeated number
        elif count == 0:
            missing = v  # v never appears -> it is the missing number
    return [repeat, missing]

def findRepeatMissing(nums: List[int]) -> List[int]:
    n = len(nums)  # values should cover 1..n
    count = [0] * (n + 1)  # count[v] = occurrences of value v (slot 0 unused)
    # Pass 1: tally every array value in O(1) each
    for x in nums:
        count[x] += 1  # one more occurrence of x
    repeat, missing = -1, -1  # to be discovered in the tally
    # Pass 2: read the tally — 2 means repeated, 0 means missing
    for v in range(1, n + 1):
        if count[v] == 2:
            repeat = v   # seen twice
        elif count[v] == 0:
            missing = v  # never seen
    return [repeat, missing]

def inversionCount(arr: List[int]) -> int:
    n = len(arr)  # number of elements
    count = 0  # running inversion total
    # Check every pair (i, j) with i < j — the literal definition
    for i in range(n):
        for j in range(i + 1, n):
            # Inversion: earlier element strictly bigger than a later one
            if arr[i] > arr[j]:
                count += 1  # found one out-of-order pair
    return count  # total number of inversions

def searchMatrix(matrix: List[List[int]], target: int) -> bool:
    # Look at every cell, ignoring the sorted structure entirely
    for row in matrix:
        for val in row:
            # Direct comparison against the target
            if val == target:
                return True  # found a match — stop immediately
    return False  # scanned all m*n cells without a hit

def searchMatrix(matrix: List[List[int]], target: int) -> bool:
    m, n = len(matrix), len(matrix[0])  # dimensions
    r, c = 0, n - 1  # start at the TOP-RIGHT corner
    # Corner property: left neighbours are smaller, lower neighbours bigger
    while r < m and c >= 0:
        val = matrix[r][c]  # current corner of the surviving sub-matrix
        if val == target:
            return True  # found it
        elif val > target:
            c -= 1  # whole column below is even bigger — discard it, step left
        else:
            r += 1  # whole row to the left is even smaller — discard it, step down
    return False  # walked off the matrix: the target cannot exist

def searchMatrix(matrix: List[List[int]], target: int) -> bool:
    m, n = len(matrix), len(matrix[0])  # rows, cols
    # Key insight: read row-by-row, the whole matrix is ONE sorted
    # list of m*n values — so run a single binary search on it.
    lo, hi = 0, m * n - 1  # virtual 1-D search window
    while lo <= hi:
        mid = (lo + hi) // 2  # middle virtual index
        # Un-flatten: virtual index -> real cell (row = mid // n, col = mid % n)
        val = matrix[mid // n][mid % n]
        if val == target:
            return True  # found the target
        elif val < target:
            lo = mid + 1  # target can only live in the right half
        else:
            hi = mid - 1  # target can only live in the left half
    return False  # window emptied without ever hitting the target

def is_valid_bst(root):
    # For EVERY node, re-scan its ENTIRE left subtree (all values must be
    # smaller) and its ENTIRE right subtree (all values must be larger).

    def subtree_ok(node, check):
        # True only if EVERY value in this subtree passes 'check'.
        if node is None:
            return True                     # an empty subtree has no violators
        if not check(node.val):
            return False                    # this value breaks the ancestor's rule
        # both children's subtrees must also fully satisfy the rule
        return subtree_ok(node.left, check) and subtree_ok(node.right, check)

    def valid(node):
        if node is None:
            return True                     # an empty tree is a valid BST
        # rule 1: everything on the left is strictly smaller than node.val
        if not subtree_ok(node.left, lambda v: v < node.val):
            return False
        # rule 2: everything on the right is strictly larger than node.val
        if not subtree_ok(node.right, lambda v: v > node.val):
            return False
        # rule 3: both subtrees must themselves be valid BSTs
        return valid(node.left) and valid(node.right)

    return valid(root)                      # start the check at the root

def lowest_common_ancestor(root, p, q):
    # BST insight: walking down from the root, the FIRST node where p and q
    # split apart (one on each side, or equal to it) is their LCA.
    node = root                       # begin the descent at the root
    while node:                       # one root-to-LCA walk, no backtracking
        if p < node.val and q < node.val:
            node = node.left          # both targets live in the left subtree
        elif p > node.val and q > node.val:
            node = node.right         # both targets live in the right subtree
        else:
            return node               # they straddle (or one equals) => LCA
    return None                       # empty tree: nothing to return

def bst_from_preorder(preorder):
    # Preorder visits the root FIRST, so inserting the values one-by-one
    # with the standard BST insert recreates exactly the original tree.

    def insert(node, val):
        # Standard BST insert: walk down and attach a new leaf in place.
        if node is None:
            return TreeNode(val)            # found the empty slot: create the node
        if val < node.val:
            node.left = insert(node.left, val)    # smaller values go left
        else:
            node.right = insert(node.right, val)  # larger values go right
        return node                         # hand back the (unchanged) subtree root

    root = None                             # start from an empty tree
    for val in preorder:                    # n inserts in preorder order
        root = insert(root, val)            # each insert costs O(h) — up to O(n)
    return root                             # sorted input => skewed tree => O(n^2) total

class BSTIterator:
    # Eager approach: do ALL the work up front — flatten the whole tree.
    def __init__(self, root: Optional[TreeNode]):
        self.vals = []           # will hold every value, in sorted order
        self.idx = -1            # index of the value we handed out last
        self._inorder(root)      # one full traversal fills self.vals

    def _inorder(self, node):
        if not node:
            return               # empty subtree contributes nothing
        self._inorder(node.left)     # smaller values first (left subtree)
        self.vals.append(node.val)   # then the node itself
        self._inorder(node.right)    # larger values last (right subtree)

    def next(self) -> int:
        self.idx += 1                # advance to the next stored value
        return self.vals[self.idx]   # O(1) list read

    def hasNext(self) -> bool:
        return self.idx + 1 < len(self.vals)  # True while values remain

class BSTIterator:
    # Lazy inorder: keep ONLY the pending left spine on a stack, not the whole tree.
    def __init__(self, root: Optional[TreeNode]):
        self.stack = []        # nodes whose values are still owed to the caller
        self._push_left(root)  # stage the path down to the smallest value

    def _push_left(self, node):
        # Dive down the left edge, stacking every node we pass.
        while node:
            self.stack.append(node)  # this node's value comes before its right subtree
            node = node.left         # smaller values live down-left

    def next(self) -> int:
        node = self.stack.pop()      # top of the stack IS the next smallest value
        self._push_left(node.right)  # values just after it live in its right subtree
        return node.val              # emit values in sorted order

    def hasNext(self) -> bool:
        return len(self.stack) > 0   # values remain while the stack is non-empty

def findTarget(root: Optional[TreeNode], k: int) -> bool:
    vals = []                        # every value in the tree, any order
    def collect(node):
        if not node:
            return                   # empty subtree: nothing to record
        vals.append(node.val)        # record this node's value
        collect(node.left)           # gather the whole left side
        collect(node.right)          # gather the whole right side
    collect(root)                    # vals now holds all n values
    n = len(vals)
    # Try every unordered pair (i, j) of two DIFFERENT nodes
    for i in range(n):
        for j in range(i + 1, n):    # j > i guarantees two distinct nodes
            if vals[i] + vals[j] == k:
                return True          # found a pair summing to k
    return False                     # no pair of distinct nodes works

def findTarget(root: Optional[TreeNode], k: int) -> bool:
    seen = set()                     # values of all nodes visited so far
    def dfs(node):
        if not node:
            return False             # an empty subtree cannot complete a pair
        if k - node.val in seen:     # a previously seen node is the exact partner
            return True
        seen.add(node.val)           # remember this value for future nodes
        # The partner may live in either subtree — search both
        return dfs(node.left) or dfs(node.right)
    return dfs(root)                 # one pass over the tree decides it

def findTarget(root: Optional[TreeNode], k: int) -> bool:
    arr = []                     # inorder traversal of a BST comes out SORTED
    def inorder(node):
        if not node:
            return               # base case: an empty subtree adds nothing
        inorder(node.left)       # smaller values first
        arr.append(node.val)     # then this node's value
        inorder(node.right)      # larger values last
    inorder(root)                # after this call, arr is sorted ascending
    lo, hi = 0, len(arr) - 1     # two pointers at the two extremes
    while lo < hi:               # need two DIFFERENT nodes, so stop when they meet
        s = arr[lo] + arr[hi]    # candidate pair sum
        if s == k:
            return True          # exact pair found
        if s < k:
            lo += 1              # sum too small -> take a bigger left value
        else:
            hi -= 1              # sum too big -> take a smaller right value
    return False                 # pointers met without a match: no such pair

def largestBst(root: Optional[TreeNode]) -> int:
    # Is the subtree at node a BST whose values all lie strictly in (low, high)?
    def is_bst(node, low, high):
        if not node:
            return True                      # an empty tree is a valid BST
        if not (low < node.val < high):
            return False                     # value violates an ancestor's range
        # Left values must stay below node.val, right values above it
        return is_bst(node.left, low, node.val) and is_bst(node.right, node.val, high)

    def count(node):
        if not node:
            return 0                         # empty subtree has zero nodes
        return 1 + count(node.left) + count(node.right)  # node plus both sides

    def solve(node):
        if not node:
            return 0                         # nothing here to measure
        if is_bst(node, float('-inf'), float('inf')):
            return count(node)               # whole subtree valid -> its size wins here
        # Otherwise the best BST lives strictly inside one of the children
        return max(solve(node.left), solve(node.right))

    return solve(root)                       # best size over every subtree

def isCycle(V, adj):
    # Backtracking search: try to close a loop around each "anchor" vertex
    def explore(start, node, on_path, edges_used):
        # Walk every edge leaving the current end of the path
        for nei in adj[node]:
            # Stepping back onto the anchor after >= 3 edges closes a REAL
            # cycle (2 edges would just be the same edge walked both ways)
            if nei == start and edges_used + 1 >= 3:
                return True
            # Extend the simple path only with vertices not already on it
            if nei not in on_path:
                on_path.add(nei)                    # take the step
                if explore(start, nei, on_path, edges_used + 1):
                    return True                     # a cycle closed deeper down
                on_path.remove(nei)                 # backtrack: undo the step
        # No extension of this particular path loops back to the anchor
        return False

    for s in range(V):
        # A fresh path {s} for every possible anchor vertex
        if explore(s, s, {s}, 0):
            return True
    # No anchor vertex lies on any loop of length >= 3
    return False

def isCycle(V, adj):
    # visited[u] is True once DFS has discovered vertex u
    visited = [False] * V

    def dfs(node, parent):
        # Discover the current vertex
        visited[node] = True
        # Walk every edge leaving node
        for nei in adj[node]:
            if not visited[nei]:
                # Tree edge: dive deeper; bubble a found cycle straight up
                if dfs(nei, node):
                    return True
            elif nei != parent:
                # Already-visited neighbour that is NOT the vertex we came
                # from: we found a second route to nei, i.e. a cycle
                return True
        # No cycle anywhere in the subtree hanging below node
        return False

    # The graph may be disconnected — start a DFS in every fresh component
    for s in range(V):
        if not visited[s]:
            # -1 is a sentinel parent: the root of a DFS tree has no parent
            if dfs(s, -1):
                return True
    # All components searched, no back edge found anywhere
    return False

def isCyclic(V, adj):
    # Colours: 0 = white (untouched), 1 = grey (on the CURRENT recursion
    # path), 2 = black (fully processed — provably leads to no cycle)
    color = [0] * V

    def dfs(u):
        # Entering u puts it on the active recursion path
        color[u] = 1
        for v in adj[u]:
            # A grey neighbour is an ancestor still on our path: back edge!
            if color[v] == 1:
                return True
            # Recurse only into white vertices; black ones are already safe
            if color[v] == 0 and dfs(v):
                return True
        # Leaving u: nothing below it loops back, mark it safe forever
        color[u] = 2
        return False

    # The graph may be disconnected — try every still-white vertex as a root
    for s in range(V):
        if color[s] == 0 and dfs(s):
            return True
    # No back edge found anywhere in any component
    return False

def floyd_warshall(mat):
    # n vertices; mat[i][j] == 10^8 is the sentinel for "no direct edge"
    n = len(mat)
    INF = 10**8
    # Collect the real directed edges once as (u, v, weight) triples
    edges = []
    for u in range(n):
        for v in range(n):
            # skip missing edges and the diagonal (u -> u is always 0)
            if u != v and mat[u][v] != INF:
                edges.append((u, v, mat[u][v]))
    # Run one full Bellman-Ford from EVERY possible source vertex
    answer = []
    for src in range(n):
        dist = [INF] * n            # best-known cost from src to each vertex
        dist[src] = 0               # reaching yourself is free
        # n-1 relaxation passes finalise every shortest path from src
        for _ in range(n - 1):
            for u, v, w in edges:   # try to improve v by going through u
                if dist[u] != INF and dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w   # cheaper route found
        answer.append(dist)         # one finished row of the answer
    # The problem wants the matrix updated IN PLACE, so copy rows back
    for i in range(n):
        for j in range(n):
            mat[i][j] = answer[i][j]    # overwrite with the shortest cost
    return mat                      # also return it, for convenience

def spanning_tree(V, edges):
    # Kruskal core idea: always try the cheapest remaining edge first
    order = sorted(edges, key=lambda e: e[2])   # sort by weight
    # comp[v] = id of the connected component v belongs to right now;
    # initially every vertex sits alone in its own component
    comp = list(range(V))
    total = 0                       # running MST weight
    used = 0                        # number of edges accepted so far
    for u, v, w in order:
        if comp[u] == comp[v]:
            continue                # same component: edge would close a cycle
        total += w                  # different components: accept the edge
        used += 1
        old, new = comp[v], comp[u]     # merge v's component into u's
        # naive merge: relabel EVERY vertex that carries v's old id
        for x in range(V):
            if comp[x] == old:
                comp[x] = new       # x now belongs to the merged component
        if used == V - 1:
            break                   # a spanning tree has exactly V-1 edges
    return total                    # sum of the MST edge weights

def maxSumNonAdjacent(nums: List[int]) -> int:
    # solve(i) = best non-adjacent sum achievable using ONLY indices 0..i
    def solve(i: int) -> int:
        # an empty prefix has nothing to offer
        if i < 0:
            return 0
        # with just index 0 available, the best move is to take it
        if i == 0:
            return nums[0]
        # Choice 1: TAKE nums[i] — index i-1 becomes forbidden, so recurse on i-2
        take = nums[i] + solve(i - 2)
        # Choice 2: SKIP nums[i] — the whole prefix 0..i-1 stays available
        skip = solve(i - 1)
        # keep whichever choice earns more money
        return max(take, skip)

    # the answer uses the full array: the prefix ending at the last index
    return solve(len(nums) - 1)

def rob(nums: List[int]) -> int:
    n = len(nums)  # number of houses on the circle
    # a lone house has no neighbour — rob it outright
    if n == 1:
        return nums[0]

    best = 0  # best loot found over all legal subsets
    # every subset of houses can be encoded as a bitmask: bit i set = rob house i
    for mask in range(1 << n):
        valid = True  # assume legal until an adjacent pair is found
        for i in range(n):
            # neighbour on a circle: house (i+1) % n — the last wraps to the first
            if (mask >> i) & 1 and (mask >> ((i + 1) % n)) & 1:
                valid = False  # two adjacent houses robbed -> alarm
                break
        if valid:
            # sum the money of every robbed house in this legal plan
            total = sum(nums[i] for i in range(n) if (mask >> i) & 1)
            best = max(best, total)  # keep the richest legal plan
    return best

def frogJump(heights: List[int]) -> int:
    # solve(i) = minimum energy for the frog to reach stone i from stone 0
    def solve(i: int) -> int:
        # the frog starts on stone 0 — no energy spent yet
        if i == 0:
            return 0
        # arrive with a single hop from stone i-1, paying the height gap
        one = solve(i - 1) + abs(heights[i] - heights[i - 1])
        # arrive with a double jump from stone i-2 — only legal if it exists
        two = float('inf')  # sentinel: impossible at i == 1
        if i > 1:
            two = solve(i - 2) + abs(heights[i] - heights[i - 2])
        # the cheaper arrival wins
        return min(one, two)

    # answer: cheapest way to stand on the last stone
    return solve(len(heights) - 1)

def frogJumpK(heights: List[int], k: int) -> int:
    # solve(i) = minimum energy to travel from stone 0 to stone i
    def solve(i: int) -> int:
        # the frog starts on stone 0 — nothing spent yet
        if i == 0:
            return 0
        best = float('inf')  # cheapest arrival found so far
        # the final jump could have started at any of the k stones behind i
        for j in range(1, k + 1):
            # stone i-j must actually exist — stop at the left edge
            if i - j < 0:
                break
            # route cost: solve the launch stone first, then pay the height gap
            best = min(best, solve(i - j) + abs(heights[i] - heights[i - j]))
        return best

    # answer: cheapest way to stand on the last stone
    return solve(len(heights) - 1)

def frogJumpK(heights: List[int], k: int) -> int:
    memo = {}  # stone index -> min energy to reach it (computed once)

    def solve(i: int) -> int:
        # base: the frog starts on stone 0 for free
        if i == 0:
            return 0
        # cached? return the stored answer instead of recursing again
        if i in memo:
            return memo[i]
        best = float('inf')  # cheapest arrival found so far
        # try every legal launch stone among the k stones behind i
        for j in range(1, k + 1):
            if i - j < 0:
                break  # ran off the left edge — no more candidates
            # cost = cheapest way to reach the launch stone + this jump
            best = min(best, solve(i - j) + abs(heights[i] - heights[i - j]))
        memo[i] = best  # store before returning: each stone solved once
        return best

    return solve(len(heights) - 1)

def climbStairs(n: int) -> int:
    # solve(step) = number of distinct ways to climb exactly `step` stairs
    def solve(step: int) -> int:
        # base cases: 1 way to stay at the bottom, 1 way to reach step 1
        if step <= 1:
            return 1
        # the LAST move was either a 1-step (from step-1) or a 2-step (from step-2);
        # those two families of paths never overlap, so their counts add up
        return solve(step - 1) + solve(step - 2)

    # count all ways to reach the top step n
    return solve(n)

def climbStairs(n: int) -> int:
    memo = {}  # step -> number of ways (each computed exactly once)

    def solve(step: int) -> int:
        # base cases: one way to stand at step 0, one way to reach step 1
        if step <= 1:
            return 1
        # already counted this step? reuse the cached answer
        if step in memo:
            return memo[step]
        # disjoint families: last move 1-step vs last move 2-step
        memo[step] = solve(step - 1) + solve(step - 2)  # store, then return
        return memo[step]

    return solve(n)  # total ways to reach the top step n

def preorderTraversal(root: Optional[TreeNode]) -> List[int]:
    result = []                  # collects values in Root -> Left -> Right order
    # An empty tree produces an empty traversal
    if not root:
        return result

    # The stack holds nodes whose subtrees are still waiting to be visited;
    # we seed it with the root, the very first node preorder prints
    stack = [root]

    # Keep working while at least one subtree is unprocessed
    while stack:
        node = stack.pop()           # take the most recently deferred node
        result.append(node.val)      # visit it IMMEDIATELY — that is "pre"-order
        # Push RIGHT before LEFT: the stack is LIFO, so the left child
        # pops first — exactly the order preorder demands
        if node.right:
            stack.append(node.right) # right child waits underneath
        if node.left:
            stack.append(node.left)  # left child sits on top, popped next

    return result                    # e.g. [1, 2, 4, 5, 3] for the sample tree

def topoSort(V, adj):
    # order collects the final topological sequence, one vertex per round
    order = []
    # placed[u] is True once u has been added to the order
    placed = [False] * V
    # we must place all V vertices, so run exactly V rounds
    for _ in range(V):
        # scan for a vertex whose every incoming edge starts at a placed vertex
        for u in range(V):
            if placed[u]:
                continue  # u is already in the order, skip it
            # look for any UNPLACED vertex x that still points into u
            blocked = False
            for x in range(V):
                if not placed[x] and u in adj[x]:
                    blocked = True  # edge x -> u exists and x is not placed yet
                    break
            # no unplaced prerequisite remains -> u is safe to emit next
            if not blocked:
                order.append(u)
                placed[u] = True
                break
    return order

def topoSort(V, adj):
    # order collects the final topological sequence
    order = []
    placed = [False] * V  # placed[u]: u has already been emitted
    # exactly one vertex gets placed per round -> V rounds total
    for _ in range(V):
        # recompute in-degrees of the REMAINING graph from scratch
        indeg = [0] * V
        for u in range(V):
            if placed[u]:
                continue  # deleted vertices contribute no edges any more
            for v in adj[u]:
                if not placed[v]:
                    indeg[v] += 1  # a still-live edge u -> v
        # pick the first unplaced vertex with zero remaining in-degree
        for u in range(V):
            if not placed[u] and indeg[u] == 0:
                order.append(u)   # safe: nothing unplaced points at u
                placed[u] = True  # "delete" u and all its outgoing edges
                break
    return order

def isBipartite(graph):
    n = len(graph)  # number of vertices
    # try every possible way to split the vertices into two sets: 2^n masks
    for mask in range(1 << n):
        # bit u of mask decides u's set: 0 or 1
        ok = True
        # verify that EVERY edge crosses between the two sets
        for u in range(n):
            for v in graph[u]:
                # extract each endpoint's set from the mask
                if (mask >> u) & 1 == (mask >> v) & 1:
                    ok = False  # an edge stays inside one set -> split fails
                    break
            if not ok:
                break
        # found one split where all edges cross -> bipartite
        if ok:
            return True
    # no split of the vertices works
    return False

def shortestPathDAG(V, edges, src=0):
    # build the adjacency list: u -> list of (v, w) weighted edges
    adj = [[] for _ in range(V)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # ---- phase 1: topological order via DFS ----
    visited = [False] * V
    order = []  # vertices in reverse topological order

    def dfs(u):
        visited[u] = True  # mark u before exploring below it
        for v, _ in adj[u]:
            if not visited[v]:
                dfs(v)  # finish all of u's descendants first
        order.append(u)  # u enters only after everything it reaches

    # cover disconnected parts of the DAG too
    for u in range(V):
        if not visited[u]:
            dfs(u)
    order.reverse()  # flip to get a true topological order

    # ---- phase 2: relax edges in topological order ----
    INF = float('inf')
    dist = [INF] * V  # INF = "not reachable so far"
    dist[src] = 0  # the source costs nothing to reach
    for u in order:
        # vertices still at INF cannot improve anyone
        if dist[u] != INF:
            for v, w in adj[u]:
                # does the path src -> ... -> u -> v beat the best known?
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w  # yes: record the shorter cost

    # convention: report unreachable vertices as -1
    return [d if d != INF else -1 for d in dist]

def dijkstra(V, adj, src):
    INF = float('inf')
    # dist[u] = best known cost from src to u so far
    dist = [INF] * V
    dist[src] = 0  # the source is free to reach
    # finalized[u] = True once u's distance can never improve again
    finalized = [False] * V
    # each round finalizes exactly one vertex -> at most V rounds
    for _ in range(V):
        # linear scan: find the CLOSEST vertex not yet finalized
        u, best = -1, INF
        for x in range(V):
            if not finalized[x] and dist[x] < best:
                u, best = x, dist[x]
        # nothing reachable remains -> every leftover vertex is cut off
        if u == -1:
            break
        finalized[u] = True  # u's distance is now provably final
        # relax every edge leaving u
        for v, w in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w  # found a cheaper route to v
    return dist

class Trie:
    def __init__(self):
        # The most literal storage possible: keep every inserted word in a list.
        self.words = []                      # duplicates are kept, order does not matter

    def insert(self, word: str) -> None:
        self.words.append(word)              # O(1): just remember one more copy

    def countWordsEqualTo(self, word: str) -> int:
        # Walk the whole bag and count exact matches.
        return sum(1 for w in self.words if w == word)   # O(N) comparisons of length L

    def countWordsStartingWith(self, prefix: str) -> int:
        # str.startswith compares up to len(prefix) characters per stored word.
        return sum(1 for w in self.words if w.startswith(prefix))   # O(N * L)

    def erase(self, word: str) -> None:
        if word in self.words:               # guard: erasing a missing word is a no-op
            self.words.remove(word)          # removes ONE occurrence, O(N) shift

from collections import Counter

class Trie:
    def __init__(self):
        # Two hash maps instead of a tree: one for whole words, one for prefixes.
        self.word_count = Counter()          # word -> how many copies were inserted
        self.prefix_count = Counter()        # prefix string -> how many words start with it

    def insert(self, word: str) -> None:
        self.word_count[word] += 1           # one more copy of the exact word
        # Register EVERY prefix, including the empty one so that "" counts all words.
        for i in range(len(word) + 1):
            self.prefix_count[word[:i]] += 1  # word[:i] builds a fresh string: O(i) work

    def countWordsEqualTo(self, word: str) -> int:
        return self.word_count[word]         # Counter returns 0 for unseen keys

    def countWordsStartingWith(self, prefix: str) -> int:
        return self.prefix_count[prefix]     # answer was precomputed at insert time

    def erase(self, word: str) -> None:
        if self.word_count[word] == 0:       # guard so counters never go negative
            return
        self.word_count[word] -= 1           # undo the exact-word bump
        for i in range(len(word) + 1):
            self.prefix_count[word[:i]] -= 1  # undo every prefix bump, mirroring insert

class StockSpanner:
    def __init__(self):
        self.prices = []                 # the full price history, oldest first

    def next(self, price: int) -> int:
        self.prices.append(price)        # today's quote joins the history
        span = 1                         # today itself always counts
        i = len(self.prices) - 2         # start looking at YESTERDAY
        # Walk backwards while the older prices stay <= today's price.
        while i >= 0 and self.prices[i] <= price:
            span += 1                    # one more consecutive day qualifies
            i -= 1                       # step further into the past
        return span                      # stops at the first strictly greater day

def coinChange(coins: List[int], amount: int) -> int:
    # INF stands for "this amount can never be built" - bigger than any real answer
    INF = float('inf')

    # solve(i, rem) = fewest coins needed for `rem` using only coin types i, i+1, ...
    def solve(i: int, rem: int):
        # exact change reached: no more coins required on this path
        if rem == 0:
            return 0
        # ran out of coin types while money is still owed -> dead branch
        if i == len(coins):
            return INF
        # Choice 1: ignore coin type i for good and move on to the next type
        not_take = solve(i + 1, rem)
        # Choice 2: spend ONE coin of type i (coins are unlimited, so i stays)
        take = INF
        if coins[i] <= rem:
            take = 1 + solve(i, rem - coins[i])
        # the better of the two decisions wins
        return min(take, not_take)

    ans = solve(0, amount)          # start with every coin type available
    # INF survived -> the target is unreachable, the problem asks for -1
    return -1 if ans == INF else int(ans)

def minCut(s: str) -> int:
    n = len(s)                      # length of the string we must partition
    # an empty string or one character is already a palindrome: zero cuts
    if n <= 1:
        return 0
    # pal[i][j] answers "is s[i..j] a palindrome?" in O(1) once it is filled
    pal = [[False] * n for _ in range(n)]
    # i goes BACKWARDS so the shorter inner window pal[i + 1][j - 1] is ready first
    for i in range(n - 1, -1, -1):
        # j goes forwards and always stays to the right of i
        for j in range(i, n):
            # the two ends must match AND the strip between them must be a palindrome
            if s[i] == s[j] and (j - i < 2 or pal[i + 1][j - 1]):
                pal[i][j] = True    # windows of length 1 or 2 skip the inner check
    # dp[j] = fewest cuts needed to split the prefix s[0..j] into palindromes
    dp = [0] * n
    for j in range(n):
        # if the whole prefix is already a palindrome, no cut is needed at all
        if pal[0][j]:
            dp[j] = 0
        else:
            best = j                # worst case: cut between every pair of characters
            # the LAST piece is s[i..j]; it is only legal if it is a palindrome
            for i in range(1, j + 1):
                # one cut just before i, plus the best cuts for the prefix s[0..i-1]
                if pal[i][j] and dp[i - 1] + 1 < best:
                    best = dp[i - 1] + 1
            dp[j] = best            # store the best cut count for this prefix
    # the whole string is the prefix ending at the last index
    return dp[n - 1]

def top_k_frequent(nums, k):
    # Collect the distinct values, preserving first-seen order.
    uniques = []
    for num in nums:
        # 'in' on a list is an O(u) scan -- this is the slow part.
        if num not in uniques:
            uniques.append(num)
    # Count each distinct value with another full scan of nums.
    pairs = []
    for value in uniques:
        # list.count walks the whole array once per distinct value.
        pairs.append((nums.count(value), value))
    # Selection-sort style: pull out the current best k times.
    result = []
    for _ in range(k):
        best_index = 0
        for idx in range(1, len(pairs)):
            # Compare counts only; ties may go either way.
            if pairs[idx][0] > pairs[best_index][0]:
                best_index = idx
        # Remove the winner so the next round finds the next best.
        result.append(pairs.pop(best_index)[1])
    return result

class MedianFinder:
    def __init__(self):
        # Keep every number in arrival order; no ordering maintained.
        self.data = []

    def addNum(self, num):
        # O(1): just remember the value, do no work yet.
        self.data.append(num)

    def findMedian(self):
        # Pay the full sorting cost on EVERY query.
        ordered = sorted(self.data)      # O(n log n) each call
        n = len(ordered)
        # Odd count -> the single middle element is the median.
        if n % 2 == 1:
            return float(ordered[n // 2])
        # Even count -> average the two middle elements.
        return (ordered[n // 2 - 1] + ordered[n // 2]) / 2.0

import bisect

class MedianFinder:
    def __init__(self):
        # Invariant: self.data is ALWAYS sorted ascending.
        self.data = []

    def addNum(self, num):
        # bisect finds the insertion point in O(log n)...
        # ...but insort still shifts elements, so the insert itself is O(n).
        bisect.insort(self.data, num)

    def findMedian(self):
        # The list is already sorted, so the median is a direct index lookup.
        n = len(self.data)
        # Odd count -> exact middle element.
        if n % 2 == 1:
            return float(self.data[n // 2])
        # Even count -> mean of the two middles.
        return (self.data[n // 2 - 1] + self.data[n // 2]) / 2.0

import heapq                                        # heapq is a MIN-heap only

class MedianFinder:
    def __init__(self):
        # 'low' is the SMALLER half, kept as a max-heap by storing negated values.
        self.low = []                              # -(largest of the small half) sits at low[0]
        # 'high' is the LARGER half, a plain min-heap.
        self.high = []                             # smallest of the big half sits at high[0]

    def addNum(self, num):
        # 1) Always enter through 'low' so num is ranked against the small half.
        heapq.heappush(self.low, -num)             # negate to fake a max-heap
        # 2) Hand low's largest over to 'high': guarantees every low value <= every high value.
        heapq.heappush(self.high, -heapq.heappop(self.low))
        # 3) Rebalance so low has the same size as high, or exactly one more.
        if len(self.high) > len(self.low):
            heapq.heappush(self.low, -heapq.heappop(self.high))

    def findMedian(self):
        # Odd total -> low holds the extra element, so its top IS the median.
        if len(self.low) > len(self.high):
            return float(-self.low[0])
        # Even total -> average the two middles, one sitting at each root.
        return (-self.low[0] + self.high[0]) / 2.0

def setZeroes(matrix: List[List[int]]) -> None:
    m, n = len(matrix), len(matrix[0])
    col0 = 1 # Flag to track first column state

    # Step 1: Set flags in the first row and column
    for i in range(m):
        # Check if first column has any zero
        if matrix[i][0] == 0:
            col0 = 0
        # Check rest of the cells
        for j in range(1, n):
            if matrix[i][j] == 0:
                matrix[i][0] = 0 # Mark row start
                matrix[0][j] = 0 # Mark col start

    # Step 2: Traverse matrix backwards to set zeroes
    for i in range(m - 1, -1, -1):
        for j in range(n - 1, 0, -1):
            # If row start or col start is zero, set current cell to zero
            if matrix[i][0] == 0 or matrix[0][j] == 0:
                matrix[i][j] = 0
        # Update the first column cell
        if col0 == 0:
            matrix[i][0] = 0

def longestConsecutive(nums: List[int]) -> int:
    # Guard first: the walk below reads s[0], so an empty array needs its own answer
    if not nums:
        return 0

    # sorted() returns a NEW list, so the caller's array is left untouched
    s = sorted(nums)

    longest = 1                       # with >=1 element the answer is at least 1
    streak = 1                        # length of the run ending at index i

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            # Duplicate value: it adds nothing to the run.
            # [1,1,2] must count as 2, not 3 - so do NOT touch streak.
            continue
        elif s[i] == s[i - 1] + 1:
            streak += 1               # the run continues by exactly one
        else:
            streak = 1                # gap found: start a fresh run here

        # Update the record after every genuine (non-duplicate) step
        longest = max(longest, streak)

    return longest

def threeSum(nums: List[int]) -> List[List[int]]:
    n = len(nums)
    # A set of SORTED tuples: two index-triples holding the same values
    # (e.g. two different -1s) collapse into one entry automatically.
    found = set()

    # Strictly increasing indices i < j < k means:
    #   * no element is ever reused, and
    #   * each combination is tested exactly once (not 6 times).
    for i in range(n - 2):
        for j in range(i + 1, n - 1):
            for k in range(j + 1, n):
                # The only test there is
                if nums[i] + nums[j] + nums[k] == 0:
                    # Sort the VALUES so [-1,0,1] and [0,-1,1] are the same key
                    triplet = tuple(sorted((nums[i], nums[j], nums[k])))
                    found.add(triplet)

    # Turn the de-duplicated tuples back into the required list-of-lists,
    # sorted so the output order is deterministic and easy to compare.
    return sorted([list(t) for t in found])

def subsetSums(arr: List[int]) -> List[int]:
    # Better: build the answer incrementally instead of re-summing every subset.
    sums = [0]                                     # with zero elements there is one subset: {}
    for x in arr:                                  # fold the elements in one at a time
        # Every subset seen so far spawns a twin that also contains x, so the list DOUBLES.
        # Each new total costs a single addition, not a full re-scan of the subset.
        sums += [s + x for s in sums]              # old subsets (without x) + new ones (with x)
    sums.sort()                                    # increasing order, as the question demands
    return sums                                    # length is 2^len(arr)

def search(nums: List[int], target: int) -> int:
    low, high = 0, len(nums) - 1  # the search window starts as the whole array

    while low <= high:  # keep going while the window is non-empty
        mid = low + (high - low) // 2  # overflow-safe midpoint of the window
        if nums[mid] == target:  # direct hit?
            return mid  # values are distinct, so this is THE index

        # Case 1: Left half is sorted
        if nums[low] <= nums[mid]:
            if nums[low] <= target < nums[mid]:
                high = mid - 1 # Search left half
            else:
                low = mid + 1  # Search right half

        # Case 2: Right half is sorted
        else:
            if nums[mid] < target <= nums[high]:
                low = mid + 1  # Search right half
            else:
                high = mid - 1 # Search left half

    return -1  # window collapsed without ever matching

def isValid(s: str) -> bool:
    stack = []
    # Map closing brackets to opening partners
    mapping = {")": "(", "}": "{", "]": "["}

    for char in s:
        if char in mapping:
            # Pop top element or use dummy if empty
            top_element = stack.pop() if stack else '#'
            # Check if match failed
            if mapping[char] != top_element:
                return False
        else:
            # Opening bracket, push to stack
            stack.append(char)

    # Valid if stack is fully cleared
    return len(stack) == 0

class Trie:
    def __init__(self):
        # The whole "trie" is nothing but a Python list holding every word.
        # There is NO prefix sharing here: "car" and "card" are stored twice over.
        self.words = []

    def insert(self, word: str) -> None:
        # Guard against storing the same word twice; note this membership
        # test alone already scans the entire list, so insert is O(N*L).
        if word not in self.words:
            # Append keeps insertion itself cheap (amortised O(1)).
            self.words.append(word)

    def search(self, word: str) -> bool:
        # No index exists, so the only option is to look at EVERY stored word.
        for w in self.words:
            # String == compares up to L characters.
            if w == word:
                # Exact match: this word really was inserted.
                return True
        # Fell off the end of the list -> the word is absent.
        return False

    def startsWith(self, prefix: str) -> bool:
        # Again a full scan; we stop at the first word that begins with prefix.
        for w in self.words:
            # str.startswith compares at most len(prefix) characters.
            if w.startswith(prefix):
                # One matching word is enough to answer True.
                return True
        # No stored word begins with this prefix.
        return False

class TrieNode:  # one node = one position inside some word's spelling
    def __init__(self):
        # Maps characters to children TrieNodes
        self.children = {}
        self.is_word = False  # True only if an inserted word ENDS here

class Trie:  # public API: insert / search / startsWith
    def __init__(self):
        self.root = TrieNode()  # root holds no character; it is just the entry point

    def insert(self, word: str) -> None:
        curr = self.root  # cursor that walks down one level per character
        for char in word:  # one trie level per character of the word
            # Add child if not present
            if char not in curr.children:
                curr.children[char] = TrieNode()
            curr = curr.children[char]  # step down; existing paths get REUSED
        curr.is_word = True # Mark end of word

    def search(self, word: str) -> bool:
        curr = self.root  # same walk as insert, but nothing is ever created
        for char in word:
            if char not in curr.children:  # path breaks -> word was never inserted
                return False
            curr = curr.children[char]
        return curr.is_word # Must be exact word

    def startsWith(self, prefix: str) -> bool:
        curr = self.root  # identical walk; only the final answer differs
        for char in prefix:
            if char not in curr.children:  # prefix path breaks -> nothing starts with it
                return False
            curr = curr.children[char]
        return True # Prefix path exists
